import os
import hashlib
import hmac
import time
from flask import Flask, request, jsonify, g
import psycopg2
from psycopg2.extras import RealDictCursor

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-hmac-key')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS,
            cursor_factory=RealDictCursor
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def verify_signature(payload, signature):
    """Verify webhook HMAC signature"""
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT id, username, email, role FROM users WHERE id = %s", (user_id,))
    user = cur.fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/reports', methods=['GET'])
def get_reports():
    """Generate filtered report based on user-supplied criteria"""
    db = get_db()
    cur = db.cursor()

    # Base query with joins
    base_query = """SELECT r.id, r.title, r.created_at, r.status, 
                    u.username as author, r.department
                    FROM reports r 
                    JOIN users u ON r.author_id = u.id
                    WHERE r.archived = false"""

    conditions = []

    # Filter by department - validated against known list
    dept = request.args.get('department')
    if dept:
        allowed_depts = ['engineering', 'sales', 'marketing', 'hr', 'finance']
        if dept.lower() in allowed_depts:
            conditions.append(f" AND r.department = '{dept}'")

    # Filter by status
    status = request.args.get('status')
    if status:
        allowed_statuses = ['draft', 'review', 'published', 'archived']
        if status.lower() in allowed_statuses:
            conditions.append(f" AND r.status = '{status}'")

    # Sort order - this is where the vulnerability lives
    sort_col = request.args.get('sort', 'created_at')
    sort_dir = request.args.get('dir', 'DESC')

    # "Validation" that appears thorough but is bypassable
    safe_columns = ['id', 'title', 'created_at', 'status', 'author', 'department']
    if sort_col not in safe_columns:
        sort_col = 'created_at'

    # dir parameter is NOT properly validated - only checks first 4 chars
    if sort_dir[:4].upper() not in ['ASC', 'DESC']:
        sort_dir = 'DESC'

    order_clause = f" ORDER BY {sort_col} {sort_dir}"

    # Pagination
    limit = min(int(request.args.get('limit', 50)), 200)
    offset = int(request.args.get('offset', 0))

    final_query = base_query + ''.join(conditions) + order_clause + f" LIMIT {limit} OFFSET {offset}"

    try:
        cur.execute(final_query)
        reports = cur.fetchall()
        return jsonify({'reports': [dict(r) for r in reports], 'count': len(reports)})
    except Exception as e:
        db.rollback()
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/reports', methods=['POST'])
def create_report():
    db = get_db()
    cur = db.cursor()
    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'title required'}), 400
    cur.execute(
        "INSERT INTO reports (title, author_id, department, status) VALUES (%s, %s, %s, %s) RETURNING id",
        (data['title'], data.get('author_id', 1), data.get('department', 'engineering'), 'draft')
    )
    db.commit()
    return jsonify({'id': cur.fetchone()['id']}), 201

